const { ethers } = require('ethers');
const { config } = require('../lib/config');
const { log, logSuccess, logError, logHeader, colors } = require('../lib/logger');
const { signTransaction, validateSigningConfig } = require('../lib/transaction-signer');
const { publishSignedTransaction, checkInfrastructure } = require('../lib/infrastructure');
const { Client, Transaction, AccountId, TransactionId, Timestamp} = require('@hashgraph/sdk');


async function generateEvmTransaction() {
  logHeader('� Generating EVM Transaction...');
  
  const privateKey = process.env.ETHEREUM_PRIVATE_KEY;
  if (!privateKey) {
    throw new Error('ETHEREUM_PRIVATE_KEY not found in environment or config');
  }
  
  log('📡 Connecting to Hedera testnet...', colors.blue);
    
  const txParams = {
    to: "0x862f916107453fa1a2a5d8716e706e35954947ec",
    data: "",
    value: ethers.utils.parseEther("0"),
    gasLimit: 15000000,
    chainId: 296,
  };
  
  log('📝 Transaction parameters:', colors.cyan);
  log(`   • To: ${txParams.to}`, colors.dim);
  log(`   • Value: ${ethers.utils.formatEther(txParams.value)} ETH`, colors.dim);
  log(`   • Gas Limit: ${txParams.gasLimit.toLocaleString()}`, colors.dim);
  log(`   • Chain ID: ${txParams.chainId}`, colors.dim);
  log(`   • Data length: ${txParams.data.length} characters`, colors.dim);
  
  const unsignedTx = ethers.utils.serializeTransaction(txParams);
  logSuccess('✅ EVM transaction generated successfully!');
  
  return unsignedTx;
}

async function generateHederaTransaction() {
  logHeader('🪙 Generating Hedera Transaction...');
  const tx = Transaction.fromBytes(new Uint8Array(Buffer.from('', 'hex')));
  const accountId = AccountId.fromString(process.env.ACCOUNT_ID);
  const txId = TransactionId.withValidStart(accountId, Timestamp.fromDate(new Date()))
  tx.setTransactionId(txId).setTransactionValidDuration(180)
        const client = Client.forName('testnet')
  const unsignedTx = Buffer.from(tx.freezeWith(client).toBytes()).toString("hex");
        logSuccess('✅ Hedera transaction generated successfully!');
  return unsignedTx;
}

async function runTransactionSenderTest() {
  logHeader('🚀 Running Transaction Sender Test...');
  
  if (!validateSigningConfig()) {
    logError('❌ Configuration validation failed');
    return;
  }
  
  const format = config.BLOCKCHAIN_FORMAT.toLowerCase();
  log(`🔧 Blockchain format: ${format.toUpperCase()}`, colors.blue);
  
  try {
    let unsignedTx;
    
    switch (format) {
      case 'ethereum':
        unsignedTx = await generateEvmTransaction();
        break;
      case 'hedera':
        unsignedTx = await generateHederaTransaction();
        break;
      default:
        throw new Error(`Unsupported blockchain format: ${format}`);
    }
    
    logHeader('🔐 Signing Transaction...');
    const signedTx = await signTransaction(unsignedTx);
    logSuccess(`✅ ${format.toUpperCase()} transaction signed successfully!`);
    
    logHeader('📤 Publishing Transaction...');
    await publishSignedTransaction(signedTx);
    logSuccess('✅ Published signed transaction to message queue');
    
    logHeader('🎉 Transaction Sender Test Completed!');
    logSuccess(`✨ Successfully created and signed ${format.toUpperCase()} transaction`);
    logSuccess('✨ Transaction published to transaction sender service');
    
  } catch (error) {
    logError(`❌ Failed to process transaction: ${error.message}`);
    logError('💡 Troubleshooting tips:');
    logError('   • Check that your private key is valid for the selected blockchain format');
    logError('   • For Hedera: HEDERA_PRIVATE_KEY should be in DER format');
    logError('   • For Ethereum: ETHEREUM_PRIVATE_KEY should be in hex format');
    logError('   • Ensure network connectivity to the blockchain endpoint');
    throw error;
  }
}

async function main() {
  try {
    logHeader('🏦 Green Bonds Platform - Transaction Sender Test');
    log('=================================================\n', colors.bright);
    log(`� Blockchain Format: ${config.BLOCKCHAIN_FORMAT.toUpperCase()}`, colors.blue);
    log(`📅 Started at: ${new Date().toISOString()}`, colors.dim);
    
    logHeader('🔍 Checking Infrastructure...');
    const infrastructureReady = await checkInfrastructure();
    
    if (!infrastructureReady) {
      logError('❌ Infrastructure check failed - cannot proceed');
      process.exit(1);
    }
    
    logSuccess('✅ Infrastructure is ready!');
    log(''); // Empty line for better readability
    
    await runTransactionSenderTest();
    
    logHeader('✨ Transaction Sender Test Completed Successfully!');
    log(`📅 Completed at: ${new Date().toISOString()}`, colors.dim);
    
  } catch (error) {
    logError(`❌ Transaction sender test failed: ${error.message}`);
    logError(`📅 Failed at: ${new Date().toISOString()}`);
    
    if (error.stack) {
      log('\n🔍 Stack trace:', colors.dim);
      log(error.stack, colors.dim);
    }
    
    process.exit(1);
  }
}

if (require.main === module) {
  main();
}

module.exports = { runTransactionSenderTest };